mapper.update:
UPDATE herb_atlas_feature
SET is_deleted = 1,
    updated_at = NOW()
WHERE atlas_id = #{atlasId}
  AND feature_model = #{featureModel}
  AND feature_version = #{featureVersion}
  AND is_deleted = 0

UPDATE herb_atlas_feature
SET extract_time = #{extractTime},
    error_message = #{errorMessage},
    updated_at = #{updatedAt}
WHERE atlas_id = #{atlasId}
  AND feature_model = #{featureModel}
  AND feature_version = #{featureVersion}
  AND extract_status = 'failed'
  AND is_deleted = 0

mapper.select:
SELECT COUNT(1)
FROM herb_atlas_feature
WHERE atlas_id = #{atlasId}
  AND feature_model = #{featureModel}
  AND feature_version = #{featureVersion}
  AND extract_status = 'success'
  AND is_deleted = 0
LIMIT 1
